    // Collect matrix include values to know whether a matrix job can be windows.
    bool jobWindowsCapable(String runsOn, YamlMap job) {
      if (runsOn.contains('windows')) return true;
      if (!runsOn.contains('matrix')) return false;
      final strategy = job['strategy'];
      if (strategy is YamlMap && strategy['matrix'] is YamlMap) {
