            final v = inc['runner']?.toString() ?? inc['os']?.toString() ?? '';
            if (v.contains('windows')) return true;
          }
        }
        final runner = m['runner'];
        if (runner is YamlList) {
          for (final v in runner) {
            if (v.toString().contains('windows')) return true;
          }
        }
      }
      return false;
    }

    for (final e in jobs.entries) {
      final job = e.value;
      if (job is! YamlMap) continue;
      final runsOn = job['runs-on']?.toString() ?? '';
